def kessler_freight_charge(weight_kg, zone, is_perishable) -> float:
    from decimal import Decimal, ROUND_HALF_UP

    rates = {
        "inland": Decimal("4.20"),
        "coastal": Decimal("5.75"),
        "highland": Decimal("9.10"),
    }

    if zone not in rates:
        raise ValueError("invalid zone")

    weight = Decimal(str(weight_kg))
    if not weight > 0:
        raise ValueError("weight_kg must be greater than 0")

    base_rate = rates[zone]
    subtotal = min(weight, Decimal("10")) * base_rate

    if weight > 10:
        subtotal += min(weight - Decimal("10"), Decimal("40")) * base_rate * Decimal("0.60")

    if weight > 50:
        subtotal += (weight - Decimal("50")) * base_rate * Decimal("0.35")

    cents = Decimal("0.01")
    subtotal = subtotal.quantize(cents, rounding=ROUND_HALF_UP)

    if subtotal == subtotal.to_integral_value():
        subtotal -= Decimal("2.00")

    if is_perishable and zone != "highland":
        subtotal += Decimal("18.50")

    return float(subtotal.quantize(cents, rounding=ROUND_HALF_UP))

